<?php namespace App\Listeners; use App\Events\EventCancelled; use App\Jobs\RefundEventBookingsJob; use Illuminate\Contracts\Queue\ShouldQueue; class ProcessEventCancellation implements ShouldQueue {public string $queue='critical'; public int $tries=3; public array $backoff=[10,60,180]; public function handle(EventCancelled $e):void{RefundEventBookingsJob::dispatch($e->event->id)->onQueue('critical');}}
